    private fun blue(h: Float = 0f, s: Float = 1f, l: Float = 0f) = Band(BLUE, h, s, l, 30f)
    private fun magenta(h: Float = 0f, s: Float = 1f, l: Float = 0f) = Band(MAGENTA, h, s, l, 30f)

